import{_ as i,o as s,c as a,ah as r}from"./chunks/framework.CfQBrslM.js";const e="/projects/AiArm/en/latest/assets/image2.C9PUF0qF.png",n="/projects/AiArm/en/latest/assets/image3.CTuwqUPc.jpeg",l="/projects/AiArm/en/latest/assets/image4.V6MYpGTy.jpeg",o="/projects/AiArm/en/latest/assets/image5.BQnff10T.jpeg",d="/projects/AiArm/en/latest/assets/image6.FXlr8Ull.png",h="/projects/AiArm/en/latest/assets/image7.C3x_02ik.png",m="/projects/AiArm/en/latest/assets/image8.D8_4Jd4d.png",c="/projects/AiArm/en/latest/assets/image9.Dpu89jry.png",p="/projects/AiArm/en/latest/assets/image10.CnpeZSVq.png",g="/projects/AiArm/en/latest/assets/image11.BUT0C5Fo.jpeg",u="/projects/AiArm/en/latest/assets/image12.CRjIBNwU.jpeg",v="/projects/AiArm/en/latest/assets/image13.BmkhlrvU.jpeg",f="/projects/AiArm/en/latest/assets/image14.CEJqHsz5.jpeg",_="/projects/AiArm/en/latest/assets/image15.C50hpZP7.jpeg",w="/projects/AiArm/en/latest/assets/image16.DaidSz1p.jpeg",j="/projects/AiArm/en/latest/assets/image17.IUe-6iYC.jpeg",z=JSON.parse('{"title":"8. Appendix","description":"","frontmatter":{},"headers":[],"relativePath":"docs/8.Appendix.md","filePath":"docs/8.Appendix.md"}'),y={name:"docs/8.Appendix.md"};function A(b,t,x,k,T,P){return s(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_8-appendix" tabindex="-1">8. Appendix <a class="header-anchor" href="#_8-appendix" aria-label="Permalink to &quot;8. Appendix&quot;">​</a></h1><h2 id="_8-1-deviation-adjustment" tabindex="-1">8.1 Deviation Adjustment <a class="header-anchor" href="#_8-1-deviation-adjustment" aria-label="Permalink to &quot;8.1 Deviation Adjustment&quot;">​</a></h2><ol><li>If the servo main shaft deviates due to servo replacement or other operations during operating the robot arm, you need to debug the deviation. There are two types of deviation: minor deviation and large deviation. Please refer to the following instructions to debug the deviation..</li></ol><h3 id="_8-1-1-preparation" tabindex="-1">8.1.1 Preparation <a class="header-anchor" href="#_8-1-1-preparation" aria-label="Permalink to &quot;8.1.1 Preparation&quot;">​</a></h3><ol><li>Power on the robot arm, and connect it to a computer, according to the file saved in “<strong>2. AiArm Control\\ Lesson 1 AiArm PC Software</strong>”.</li></ol><h3 id="_8-1-2-judge-deviation" tabindex="-1">8.1.2 Judge Deviation <a class="header-anchor" href="#_8-1-2-judge-deviation" aria-label="Permalink to &quot;8.1.2 Judge Deviation&quot;">​</a></h3><ol><li>Click-on reset to make the robot arm extend fully straight.</li></ol><img loading="lazy" height="237" width="711" src="'+e+'" class="common_img" style="width:800px;"><ol start="2"><li>If the robot arm’s pose is as pictured, you don’t need to adjust the deviation.</li></ol><img loading="lazy" height="1248" width="1269" src="'+n+'" class="common_img" style="width:500px;"><p>​ (1) Gripper slightly closes</p><p>​ (2) The U-shaped bracket of ID2 servo is parallel to ID1 servo</p><p>​ (3) ID 3-5 servos are on the same line</p><p>​ (4) The triangular notch of the pan tilt aligns with the notch on the base.</p><ol start="3"><li>If, upon returning to the center, it appears as depicted in the figure below, it indicates that the robot arm is slightly tilted at a relatively small angle, with a range of ±30°. This can be adjusted using the slider on the PC software. Please refer to section 3, <strong>Adjust Minor Deviations,</strong> for instructions on how to make the necessary adjustments.</li></ol><img loading="lazy" height="884" width="752" src="'+l+'" class="common_img" style="width:500px;"><ol start="4"><li>If, upon returning to the center, there is a significant inclination angle as pictured, exceeding 30°. This cannot be adjusted using the servo slider. In this case, the main servo horn of the servo must be removed and recentered before reinstalling it. Please refer to section 4, <strong>Adjust Large Deviations,</strong> for detailed instructions on how to perform the adjustment.&quot;</li></ol><img loading="lazy" height="3000" width="4000" src="'+o+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ol><li><p><strong>The angle between servo and the centerline can be calculated as follows:</strong></p></li><li><p><strong>The PC software&#39;s slider range for adjusting the servo is 0 to 1000. When the servo is powered on, it can rotate from 0 to 240 degrees. Thus, the rotation angle of the servo per unit of the slider is 240/1000 = 0.24 degrees.</strong></p></li><li><p><strong>For small slider, its adjustment range is ±125. Converting this range to a small deviation, we multiply it by the rotation angle per unit of the slider: 125 * 0.24 = 30 degrees. Therefore, small slider allows for adjustments within a range of ±30 degrees for small deviations.</strong></p></li></ol></div><h3 id="_8-1-3-adjust-minor-deviation" tabindex="-1">8.1.3 Adjust Minor Deviation <a class="header-anchor" href="#_8-1-3-adjust-minor-deviation" aria-label="Permalink to &quot;8.1.3 Adjust Minor Deviation&quot;">​</a></h3><p>​ The small deviation adjustment can be made by directly dragging the servo slider on PC software. In this section, we will use the adjustment of No. 3 servo deviation as an example to explain the process. The adjustment methods for other servos are consistent and applicable.</p><ol><li>Click-on reset to make the robot arm extend fully straight.</li></ol><img loading="lazy" height="237" width="711" src="'+e+'" class="common_img" style="width:800px;"><ol start="2"><li>Click-on “<strong>Read deviation</strong>” to read the deviation of the servo. The small sliders will switch to deviation adjustment mode.</li></ol><img loading="lazy" height="478" width="783" src="'+d+'" class="common_img" style="width:800px;"><img loading="lazy" height="599" width="537" src="'+h+'" class="common_img" style="width:600px;"><ol start="3"><li>Click and hold the slider of the No. 3 servo for fine-tuning, or click the slider of the No. 3 servo and use the ← and <strong>→</strong> keys on the keyboard to make fine adjustments</li></ol><img loading="lazy" height="355" width="558" src="'+m+'" class="common_img" style="width:800px;"><ol start="4"><li>Once you finish adjustment, click-on “download deviation” to save the deviation values. Please do not skip this step.</li></ol><img loading="lazy" height="449" width="739" src="'+c+'" class="common_img" style="width:800px;"><img loading="lazy" height="639" width="754" src="'+p+'" class="common_img" style="width:800px;"><h3 id="_8-1-4-adjust-large-deviation" tabindex="-1">8.1.4 Adjust Large Deviation <a class="header-anchor" href="#_8-1-4-adjust-large-deviation" aria-label="Permalink to &quot;8.1.4 Adjust Large Deviation&quot;">​</a></h3><p>​ To adjust a large deviation, the servo needs to be removed from the U-shaped bracket, and should be centered, and then follow the steps for small deviation adjustment. In this section, we will use the ID3 servo as an example to explain the process. The adjustment method for other servos remains consistent with this procedure.</p><ol><li>Click-on reset to make the robot arm extend fully straight.</li></ol><img loading="lazy" height="237" width="711" src="'+e+'" class="common_img" style="width:800px;"><ol start="2"><li>You can see that the deviation of servo 4 is significant.</li></ol><img loading="lazy" height="3000" width="4000" src="'+o+'" class="common_img" style="width:800px;"><ol start="3"><li><p>Power off the robot arm. The following operations must be performed when the robot arm is powered off.</p></li><li><p>Remove the cover of the U-shaped bracket of servo 4.</p></li></ol><img loading="lazy" height="300" width="549" src="'+g+'" class="common_img" style="width:800px;"><ol start="5"><li>Remove the screws.</li></ol><img loading="lazy" height="355" width="643" src="'+u+'" class="common_img" style="width:800px;"><ol start="6"><li>Take down the servo.</li></ol><img loading="lazy" height="331" width="627" src="'+v+'" class="common_img" style="width:800px;"><ol start="7"><li>Slightly pull out the min servo shaft. The assistant servo shaft need not to be disassembled.</li></ol><img loading="lazy" height="388" width="835" src="'+f+'" class="common_img" style="width:800px;"><ol start="8"><li>After the servo is removed, turn on the robot, and open the PC software. Click-on Reset to center No.3 servo.</li></ol><img loading="lazy" height="237" width="711" src="'+e+'" class="common_img" style="width:800px;"><ol start="9"><li>After the servo is centered, please turn off the robot arm, and install the main servo horn and assistant servo horn in a cross pattern.</li></ol><img loading="lazy" height="238" width="416" src="'+_+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>at this point, the servo is already in the middle position. Avoid applying force to the servo shaft. If the servo is not properly installed in a cross pattern, it is necessary to repeat steps 7 to 9 of section 4, Adjust Large Deviation in this document.</strong></p></div><ol start="10"><li>After installation, put the servo back to the U-shaped bracket, and fix them with screws.</li></ol><img loading="lazy" height="285" width="517" src="'+w+'" class="common_img" style="width:800px;"><ol start="11"><li>Attach the cover to the bracket.</li></ol><img loading="lazy" height="300" width="517" src="'+j+'" class="common_img" style="width:800px;"><ol start="12"><li>Turn on the robot arm, and proceed to adjust the deviation according to the instructions provided in “<strong>3. Adjust Minor Deviation</strong>”.</li></ol>',55)])])}const D=i(y,[["render",A]]);export{z as __pageData,D as default};
